import{_ as p,a0 as n,w as d,s as l,ao as r,I as i,x as e,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"入門：如何在 Fedora Linux 中切換到深色模式 | LCTT x X-CMD","titleTemplate":false,"description":"入門：如何在 Fedora Linux 中切換到深色模式 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"入門：如何在 Fedora Linux 中切換到深色模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"入門：如何在 Fedora Linux 中切換到深色模式 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211113 How to Switch to Dark Mode in Fedora Linux -Beginner-s Tip","title":"入門：如何在 Fedora Linux 中切換到深色模式","tag":"202111","desc":""},"relativePath":"202111/20211113 How to Switch to Dark Mode in Fedora Linux -Beginner-s Tip.md","filePath":"[post].md"}'),m={name:"202111/20211113 How to Switch to Dark Mode in Fedora Linux -Beginner-s Tip.md"};function u(g,t,h,f,k,w){const s=n("Link");return d(),l("div",null,[t[18]||(t[18]=r('<h1 id="入門-如何在-fedora-linux-中切換到深色模式" tabindex="-1">入門：如何在 Fedora Linux 中切換到深色模式 <a class="header-anchor" href="#入門-如何在-fedora-linux-中切換到深色模式" aria-label="Permalink to “入門：如何在 Fedora Linux 中切換到深色模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202111/20/114412oqqw4mdnxbwfbprb.jpg" alt=""></p><p>與 Ubuntu 不同，Fedora 提供的是真正的、原生般的 GNOME 體驗，而且體驗很好，橫向佈局、三指滑動，一切都很好。</p><p>我不喜歡的一點是默認的標準主題，它是 Adwaita Light（默認）主題和深色的 GNOME Shell 的混合體。</p><p>因此，雖然通知和通知區是深色的，但系統和應用的其他部分是淺色主題。老實説，對我來説，這看起來很不協調。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/fedora-gnome-standard-theme.webp?resize=800%2C450&amp;ssl=1" alt="Fedora GNOME standard theme"></p><p>另一方面，深色主題讓它看起來更好。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/fedora-gnome-dark-theme.webp?resize=800%2C450&amp;ssl=1" alt="Fedora GNOME dark theme"></p><p>讓我告訴你如何在 Fedora 或其他任何使用 GNOME 桌面環境的發行版中開啓深色模式。</p><h3 id="在-fedora-中切換到深色模式" tabindex="-1">在 Fedora 中切換到深色模式 <a class="header-anchor" href="#在-fedora-中切換到深色模式" aria-label="Permalink to “在 Fedora 中切換到深色模式”">​</a></h3><p>好了！我將分享命令列的方法，因為它更快。打開一個終端，使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.desktop.interface gtk-theme Adwaita-dark</span></span></code></pre></div><p>完成了。這很容易，對嗎？但我也要展示一下 GUI 的方法。</p><p>因為我主要使用 Ubuntu，所以我始終參照 Ubuntu。Ubuntu 在系統設置中本身就提供了在淺色和深色主題之間切換的選項。</p>',14)),i("p",null,[t[1]||(t[1]=e("然而，在原生 GNOME 中卻沒有這樣的設置。你必須先 ",-1)),a(s,{href:"https://itsfoss.com/install-gnome-tweaks-fedora/"},{default:o(()=>[...t[0]||(t[0]=[e("在 Fedora 上安裝 GNOME Tweaks 工具",-1)])]),_:1}),t[2]||(t[2]=e("，然後用它來切換主題。",-1))]),t[19]||(t[19]=r('<p>你可以在軟件中心搜索它並點擊“<ruby>安裝<rt>Install</rt></ruby>”按鈕：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-gnome-tweaks-fedora.webp?resize=800%2C448&amp;ssl=1" alt="Install GNOME Tweaks from the software center in Fedora"></p><p>或者，你在終端輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install gnome-tweaks</span></span></code></pre></div><p>安裝完成後，按 <code>Super</code> 鍵（<code>Windows</code> 鍵）在系統菜單中搜索它：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/start-gnome-tweaks-tool-in-Fedora.png?resize=800%2C271&amp;ssl=1" alt="Start GNOME Tweaks"></p><p>點擊左側邊欄的“<ruby>外觀<rt>Appearance</rt></ruby>”標籤，點擊主題部分下的應用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/change-GTK-theme-Fedora.webp?resize=800%2C532&amp;ssl=1" alt="Changing theme in Fedora"></p><p>你會看到這裏有幾個可用的主題。你應該在這裏選擇 “Adwaita-dark”。當你選擇了它，應用就會切換到深色主題。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/switching-dark-mode-fedora.png?resize=800%2C515&amp;ssl=1" alt="Selecting the Adwaita-dark theme"></p><p>就是你在 Fedora 中切換到深色模式所需要做的一切。由於 GNOME Shell 已經在使用深色主題，你不需要明確地將它設置為深色模式。所有的通知、信息欄等都是在深色模式下的。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你可以找到各種深色 GTK 主題並安裝它們來給你的 Fedora 帶來不同的深色外觀。然而，我注意到，只有系統自己的深色主題才能被網頁瀏覽器識別。</p><p>所以，如果你訪問一個根據你的系統主題自動啓用深色模式的網站，它將與 Adwaita-dark 兼容，但可能與其他深色 GTK 主題不兼容。</p><p>這就是使用系統提供的深色主題的一個優勢。</p><p>如你所見，在 Fedora 中啓用深色模式並不是什麼火箭科學。它只是一個瞭解和發現的過程。</p><p>享受深色色彩吧！</p><hr>',18)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),a(s,{href:"https://itsfoss.com/fedora-dark-mode/"},{default:o(()=>[...t[3]||(t[3]=[e("https://itsfoss.com/fedora-dark-mode/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=e("作者：",-1)),a(s,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[5]||(t[5]=[e("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),a(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const C=p(m,[["render",u]]);export{x as __pageData,C as default};
